import * as THREE from './vendor/three.module.js';
export const ICE_FORMING=Object.freeze({limit:48,rate:60,sizeScale:3});
// Bright slide-local frost plume: stays at the growing edge through fast turns.
export class SolaraIceForming {
 constructor(parent){
  this.root=new THREE.Group();this.root.name='Solara forming ice';parent.add(this.root);this.dummy=new THREE.Object3D();this.anchor=new THREE.Vector3();
  const bandGeo=new THREE.BufferGeometry();bandGeo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(12),3).setUsage(THREE.DynamicDrawUsage));bandGeo.setAttribute('uv',new THREE.Float32BufferAttribute([0,0,1,0,0,1,1,1],2));bandGeo.setIndex([0,2,1,1,2,3]);
  const uniforms={strength:{value:0},time:{value:0}};this.uniforms=uniforms;
  this.band=new THREE.Mesh(bandGeo,new THREE.ShaderMaterial({uniforms,transparent:true,depthWrite:false,side:THREE.DoubleSide,blending:THREE.AdditiveBlending,toneMapped:false,vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:`varying vec2 vUv;uniform float strength;uniform float time;void main(){float edge=1.-abs(vUv.y*2.-1.);float ends=smoothstep(0.,.12,vUv.x)*(1.-smoothstep(.88,1.,vUv.x));float pulse=.8+.2*sin(time*5.+vUv.x*9.);gl_FragColor=vec4(.35,.8,1.,edge*ends*pulse*.65*strength);#include <colorspace_fragment>}`.replace('#include','\n#include')}));this.band.frustumCulled=false;this.root.add(this.band);
  const geometry=new THREE.PlaneGeometry(1,1);for(const name of['frostFade','frostKind'])geometry.setAttribute(name,new THREE.InstancedBufferAttribute(new Float32Array(ICE_FORMING.limit),1));
  const material=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false,vertexShader:`attribute float frostFade;attribute float frostKind;varying vec2 vUv;varying float vFade;varying float vKind;void main(){vUv=uv;vFade=frostFade;vKind=frostKind;vec4 center=modelViewMatrix*instanceMatrix*vec4(0.,0.,0.,1.);center.xy+=position.xy*vec2(length(instanceMatrix[0].xyz),length(instanceMatrix[1].xyz));gl_Position=projectionMatrix*center;}`,fragmentShader:`varying vec2 vUv;varying float vFade;varying float vKind;void main(){vec2 p=vUv*2.-1.;float mist=pow(max(0.,1.-dot(p,p)),2.);float crystal=pow(max(0.,1.-abs(p.x)-abs(p.y)),1.4);float rays=pow(max(0.,1.-abs(p.x)*abs(p.y)*38.),3.)*pow(max(0.,1.-length(p)),1.5);crystal=max(crystal,rays*.65);vec3 color=mix(vec3(.28,.7,1.),vec3(.7,.95,1.),vKind);float alpha=mix(mist*.42,crystal*.95,vKind)*vFade;gl_FragColor=vec4(color,alpha);#include <colorspace_fragment>}`.replace('#include','\n#include')});
  this.particles=new THREE.InstancedMesh(geometry,material,ICE_FORMING.limit);this.particles.frustumCulled=false;this.root.add(this.particles);this.reset();
 }
 reset(){this.items=[];this.clock=0;this.emitted=0;this.strength=0;this.anchor.set(0,0,0);this.root.visible=false;this.particles.count=0;this.uniforms.strength.value=0;}
 update(dt,time,rows,speed){
  if(rows.length<2){this.reset();return;}const tip=rows.at(-1),before=rows.at(-2),forward=tip.center.clone().sub(before.center).normalize(),side=tip.right.clone().sub(tip.left).normalize();this.anchor.copy(tip.center);this.anchor.y+=.13;
  const active=speed>.3;this.strength=THREE.MathUtils.lerp(this.strength,active?Math.min(1,speed/3):0,1-Math.exp(-9*dt));
  for(let i=this.items.length-1;i>=0;i--){const p=this.items[i];p.age+=dt;p.local.addScaledVector(p.velocity,dt);if(p.age>=p.life)this.items.splice(i,1);}
  if(active)this.clock+=dt*ICE_FORMING.rate;else this.clock=0;
  while(this.clock>=1){this.clock--;const seed=++this.emitted,a=seed*2.399,kind=seed%3===0?1:0;const p={local:new THREE.Vector3(Math.sin(a)*tip.halfWidth*.85,.03,Math.cos(a*1.7)*.12),velocity:new THREE.Vector3(Math.sin(a*1.3)*.17,.38+(seed%4)*.05,-.16),age:0,life:.5+(seed%5)*.06,size:kind?.10+(seed%3)*.02:.32+(seed%4)*.06,kind};if(this.items.length>=ICE_FORMING.limit)this.items.shift();this.items.push(p);}
  const scale=ICE_FORMING.sizeScale,positions=this.band.geometry.attributes.position;for(let i=0;i<4;i++){const p=(i%2?tip.right:tip.left).clone().sub(tip.center).multiplyScalar(scale).add(tip.center).addScaledVector(forward,(i<2?-.24:.08)*scale);p.y+=.125;positions.setXYZ(i,p.x,p.y,p.z);}positions.needsUpdate=true;this.uniforms.strength.value=this.strength;this.uniforms.time.value=time;
  let n=0;const fade=this.particles.geometry.attributes.frostFade,kind=this.particles.geometry.attributes.frostKind;for(const p of this.items){const age=p.age/p.life,size=p.size*scale*(p.kind?1:.7+age*.5);this.dummy.position.copy(this.anchor).addScaledVector(side,p.local.x*scale).addScaledVector(forward,p.local.z*scale);this.dummy.position.y+=p.local.y*scale;this.dummy.quaternion.identity();this.dummy.scale.set(size,size*(p.kind?1:.7),size);this.dummy.updateMatrix();this.particles.setMatrixAt(n,this.dummy.matrix);fade.setX(n,Math.sin(Math.PI*age)*this.strength);kind.setX(n++,p.kind);}
  this.particles.count=n;this.particles.instanceMatrix.needsUpdate=fade.needsUpdate=kind.needsUpdate=true;this.root.visible=this.strength>.005||n>0;
 }
 diagnostics(){return{active:this.root.visible,particles:this.particles.count,limit:ICE_FORMING.limit,emitted:this.emitted,strength:this.strength,anchor:this.anchor.toArray(),drawCalls:2};}
}
